WITH duplicates AS (
    SELECT id, 
    ROW_NUMBER() OVER (PARTITION BY request_id ORDER BY created_at DESC) as rn
    FROM api_logs
)
DELETE FROM api_logs WHERE id IN (SELECT id FROM duplicates WHERE rn > 1);
